import React, { useEffect, useState } from 'react';
import './App.css';
import './responsive-nav.css';
import './nav-hover.css';
import './tech-tags-animation.css';
import './project-hover.css';
import './project-size.css';
import './new-projects.css';
import './scroll-animations.css';
import './hover-fix.css';
import observeElements from './scroll-observer.js';
import AnimatedText from './components/AnimatedText';
import FaultyTerminal from './components/FaultyTerminal';
import ScrollReveal from './components/ScrollReveal';
import Balatro from './components/Balatro';

function App() {
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Initialize theme
    const savedTheme = localStorage.getItem('theme') || 'dark';
    document.body.setAttribute('data-theme', savedTheme);

    // Set initial theme toggle icon
    setTimeout(() => {
      const themeToggle = document.querySelector('.theme-toggle-fixed');
      if (themeToggle) {
        themeToggle.textContent = savedTheme === 'light' ? '☀️' : '🌙';
      }
    }, 100);

    const timer = setTimeout(() => {
      setLoading(false);
    }, 2000);

    // Parallax scroll effect
    const handleParallax = () => {
      const scrolled = window.scrollY;
      const heroVideo = document.querySelector('.hero-video');
      const heroOverlay = document.querySelector('.hero-overlay');
      const aboutBackground = document.querySelector('.about-background');

      if (heroVideo) {
        heroVideo.style.transform = `translateY(${scrolled * 0.5}px) scale(1.2)`;
      }
      if (heroOverlay) {
        heroOverlay.style.opacity = Math.min(scrolled / 500, 1);
      }
      if (aboutBackground) {
        const aboutSection = document.getElementById('about');
        if (aboutSection) {
          const aboutTop = aboutSection.offsetTop;
          const aboutScroll = scrolled - aboutTop;
          if (scrolled > aboutTop - window.innerHeight) {
            aboutBackground.style.transform = `translateY(${aboutScroll * 0.6}px)`;
          }
        }
      }
    };

    window.addEventListener('scroll', handleParallax);

    // Initialize smooth slideshow after component mounts
    const initSlideshow = () => {
      const hobbyCards = document.querySelectorAll('.hobby-card');

      hobbyCards.forEach(card => {
        const slides = card.querySelectorAll('.hobby-slide');

        // Ensure smooth transitions by preloading images
        slides.forEach((slide, index) => {
          const img = new Image();
          img.src = slide.src;

          // Set initial state
          if (index === 0) {
            slide.style.opacity = '1';
            slide.style.transform = 'scale(1)';
          } else {
            slide.style.opacity = '0';
            slide.style.transform = 'scale(1.02)';
          }
        });
      });
    };

    // Initialize after a short delay to ensure DOM is ready
    setTimeout(initSlideshow, 100);

    // Initialize scroll animations
    setTimeout(observeElements, 200);

    // Initialize cursor multiflow
    const cursor = document.createElement('div');
    cursor.className = 'cursor-main';
    document.body.appendChild(cursor);

    const trails = [];
    const trailClasses = ['cursor-trail-1', 'cursor-trail-2', 'cursor-trail-3', 'cursor-trail-4'];

    trailClasses.forEach(className => {
      const trail = document.createElement('div');
      trail.className = `cursor-trail ${className}`;
      document.body.appendChild(trail);
      trails.push(trail);
    });

    let mouseX = 0, mouseY = 0;
    const trailPositions = [];

    document.addEventListener('mousemove', (e) => {
      mouseX = e.clientX;
      mouseY = e.clientY;
      cursor.style.left = mouseX - 2 + 'px';
      cursor.style.top = mouseY - 2 + 'px';
    });

    const animateTrails = () => {
      trailPositions.unshift({ x: mouseX, y: mouseY });
      if (trailPositions.length > 20) {
        trailPositions.pop();
      }

      trails.forEach((trail, index) => {
        const delay = (index + 1) * 3;
        if (trailPositions[delay]) {
          const size = trail.offsetWidth;
          trail.style.left = trailPositions[delay].x - size/2 + 'px';
          trail.style.top = trailPositions[delay].y - size/2 + 'px';
          trail.style.opacity = 0.8 - (index * 0.15);
        }
      });

      requestAnimationFrame(animateTrails);
    };

    animateTrails();

    return () => {
      clearTimeout(timer);
      window.removeEventListener('scroll', handleParallax);
    };
  }, []);

  return (
    <div className="App">
      {/* Loading Screen */}
      <div className={`loading-screen ${!loading ? 'hidden' : ''}`}>
        <div className="loader">
          <div className="loader-text">Loading...</div>
          <div className="loader-bar"></div>
        </div>
      </div>

      {/* Scroll Progress Bar */}
      <div className="scroll-progress"></div>

      {/* Top Navigation */}
      <nav className="top-nav">
        <div className="nav-container">
          <div className="nav-brand">Akuma.co</div>
          <div className="nav-links">
            <a href="#home" className="nav-link">Home</a>
            <a href="#about" className="nav-link">About</a>
            <a href="#skills" className="nav-link">Skills</a>
            <a href="#projects" className="nav-link">Projects</a>
            <a href="#hobbies" className="nav-link">Hobbies</a>
            <a href="#photography" className="nav-link">Photography</a>
            <a href="#contact" className="nav-link">Contact</a>
          </div>
          <div className="hamburger" onClick={() => {
            const navLinks = document.querySelector('.nav-links');
            const hamburger = document.querySelector('.hamburger');
            navLinks.classList.toggle('active');
            hamburger.classList.toggle('active');
          }}>
            <span></span>
            <span></span>
            <span></span>
          </div>
        </div>
      </nav>

      {/* Side Navigation */}
      <div className="side-nav">
        <a href="#home" className="side-nav-link">Home</a>
        <a href="#about" className="side-nav-link">About</a>
        <a href="#skills" className="side-nav-link">Skills</a>
        <a href="#projects" className="side-nav-link">Projects</a>
        <a href="#hobbies" className="side-nav-link">Hobbies</a>
        <a href="#photography" className="side-nav-link">Photography</a>
        <a href="#contact" className="side-nav-link">Contact</a>
      </div>

      {/* Theme Toggle */}
      <button className="theme-toggle-fixed" onClick={(e) => {
        const body = document.body;
        const currentTheme = body.getAttribute('data-theme');
        const newTheme = currentTheme === 'light' ? 'dark' : 'light';
        body.setAttribute('data-theme', newTheme);
        localStorage.setItem('theme', newTheme);
        e.target.textContent = newTheme === 'light' ? '☀️' : '🌙';
      }}>
        🌙
      </button>

      <section id="home" className="hero">
        <div className="hero-background">
          <video autoPlay muted loop className="hero-video">
            <source src="video/1.mp4" type="video/mp4" />
          </video>
          <div className="hero-overlay"></div>
          <div className="floating-particles">
            <div className="particle"></div>
            <div className="particle"></div>
            <div className="particle"></div>
            <div className="particle"></div>
            <div className="particle"></div>
          </div>
        </div>
        <div className="hero-content">
          <div className="hero-name-container">
            <h1 className="hero-name">Bhupender</h1>
            <AnimatedText />
          </div>
        </div>
      </section>

      <section id="about" className="about-section">
        <div className="about-background">
          <FaultyTerminal
            scale={1.5}
            gridMul={[2, 1]}
            digitSize={1.2}
            timeScale={0.5}
            pause={false}
            scanlineIntensity={0.5}
            glitchAmount={1}
            flickerAmount={1}
            noiseAmp={1}
            chromaticAberration={0}
            dither={0}
            curvature={0.1}
            tint="#ff6b35"
            mouseReact
            mouseStrength={0.5}
            pageLoadAnimation={false}
            brightness={0.6}
            style={{ width: '100%', height: '100%', position: 'absolute', top: 0, left: 0 }}
          />
          <div className="about-overlay"></div>
        </div>
        <div className="about-container">
          <div className="about-content-center">
            <div className="about-badge">About Me</div>
            <h2 className="about-title">Crafting Digital Experiences</h2>
            <ScrollReveal
              baseOpacity={0.1}
              enableBlur
              baseRotation={3}
              blurStrength={4}
              textClassName="about-scroll-text"
            >
              I build digital experiences inspired by the same things that inspire me in life — visual stories, rhythm, motion, and play.

              To me, design and development are two sides of the same creative energy.

              I chase ideas that feel meaningful and make them real with precision and simplicity.

              If it feels smooth, intuitive, and a bit cinematic — that's the goal.
            </ScrollReveal>
          </div>
        </div>
      </section>

      {/* Skills Section */}
      <section id="skills" className="dashboard-section">
        <div className="dashboard-background">
          <Balatro
            isRotate={false}
            mouseInteraction
            pixelFilter={745}
            color1="#DE443B"
            color2="#006BB4"
            color3="#162325"
          />
          <div className="dashboard-overlay"></div>
        </div>
        <div className="container">
          <h2 className="section-title">Skills</h2>
        </div>
        <div className="dashboard-container">
          <div className="dashboard-grid">
                  <div className="dashboard-card progress-card">
                    <div className="card-content">
                      <h3 className="card-title">Skills</h3>
